/**
 * @distilled.cloud/openrouter — OpenRouter SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * in `.generated-specs` (written by `scripts/convert.ts` from the OpenAPI
 * spec). Everything else in this folder is hand-written.
 *
 * @example
 * ```ts
 * import * as OpenRouter from "@distilled.cloud/openrouter";
 *
 * const completion = yield* OpenRouter.createChatCompletion({
 *   model: "openai/gpt-4o-mini",
 *   messages: [{ role: "user", content: "Hello!" }],
 * });
 * ```
 */
export {
  Credentials,
  CredentialsFromEnv,
  DEFAULT_API_BASE_URL,
  credentials,
  fromApiKey,
  fromManagementKey,
} from "./credentials.ts";
export type { Config as OpenRouterClientConfig } from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  MANAGEMENT_ROUTE_PREFIXES,
  OpenRouterProtocol,
  isManagementRoute,
  selectKey,
  type OpenRouterOpError,
  type OpenRouterOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
// Operations (and their request/response types) are importable straight off
// the package root. The service-local typed error classes shadow the
// same-named shared ones from ./errors.ts — operations raise the
// service-local classes for the statuses their spec declares.
export * from "./services/openrouter.ts";
export {
  BadRequest,
  Conflict,
  Forbidden,
  GatewayTimeout,
  InsufficientCredits,
  InvalidApiKey,
  NoAvailableProvider,
  NotFound,
  ProviderError,
  ProviderOverloaded,
  ProviderTimeout,
  RateLimited,
  RequestTimeout,
  UnprocessableEntity,
} from "./services/openrouter.ts";
